from pathlib import Path
p=Path('scripts/annotate_transfer_demos.py'); s=p.read_text()
s=s.replace("'annotation_file':str(annotation_path)","'annotation_file':annotation_path.as_posix()")
s=s.replace("source_demo=str(demo),annotation_path=str(annotation_path),prepared_demo=str(output)","source_demo=demo.as_posix(),annotation_path=annotation_path.as_posix(),prepared_demo=output.as_posix()")
p.write_text(s)
p=Path('scripts/record_transfer_demos.py'); s=p.read_text(encoding='utf-8-sig')
s=s.replace('import json\n','import json\nimport os\n')
s=s.replace("path=str(dest.relative_to(output)),", "path=dest.relative_to(output).as_posix(),")
s=s.replace("source_path=str(source),", "source_path=source.as_posix(),")
s=s.replace("    if missing:\n", "    if missing or os.name=='nt':\n")
s=s.replace("status='blocked' if missing or len(eligible)!=len(validations) else 'ready'", "status='blocked' if missing or os.name=='nt' or len(eligible)!=len(validations) else 'ready',execution_runtime='Google Colab /content/micromamba/envs/libero/bin/python; Windows preparation only'")
s=s.replace("print(json.dumps(dict(blocked_by_runtime=missing,dataset=result),indent=2))", "print(json.dumps(dict(blocked_by_runtime=missing,windows_preparation_only=os.name=='nt',dataset=result),indent=2))")
s=s.replace("    for v in eligible:\n", "    for v in eligible:\n        from plan_transfer_rollouts import plan\n        preview=plan(Path(v['prepared_demo']))\n        if not preview['mapping_suitable']:\n            write_json(output/'rejected'/(v['demo_id']+'.json'),preview)\n            print('Mapping preflight rejected '+v['demo_id']+': '+str(preview['reasons']),flush=True)\n            continue\n")
p.write_text(s)
p=Path('requirements.txt'); s=p.read_text()
if 'h5py' not in s: p.write_text(s.rstrip()+'\nh5py>=3.10,<4\n')
